        <p>📚 NangSuKub — ร้านหนังสือออนไลน์ โปรเจกต์ประกอบวิชา 520 341 คณะวิทยาศาสตร์ มหาวิทยาลัยศิลปากร</p>
        <p className="text-xs">ข้อมูลหนังสือจาก fn_bn_books_44 (44เล่มคัดสรร)</p>
      </div>
    </footer>
  );
}

export default Footer;
